def solve(graph, start, goal):
    from collections import deque
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, distance = queue.pop()
        if node == goal:
            return distance
        for nxt in graph.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, distance + 1))
    return -1

