def solve(graph):
    visited = set()
    groups = 0
    for node in graph:
        if node not in visited:
            groups += 1
            stack = [node]
            visited.add(node)
            while stack:
                current = stack.pop()
                for nxt in graph[current]:
                    if nxt not in visited:
                        visited.add(current)
                        stack.append(nxt)
    return groups

