def solve(n, edges, start):
    import heapq
    graph = [[] for _ in range(n)]
    for a,b,w in edges:
        graph[a].append((b,w))
    dist = [float("inf")] * n
    dist[start] = 0
    queue = [(0,start)]
    while queue:
        cost,node = heapq.heappop(queue)
        if cost != dist[node]:
            continue
        for child,weight in graph[node]:
            candidate = cost + weight
            if candidate < dist[child]:
                dist[child] = candidate
                heapq.heappush(queue,(candidate,child))
    return [None if x == float("inf") else x for x in dist]

